// Loading, instancing, and degrading gracefully when an asset is not built yet.
//
// Assets for this scene are generated by several agents in parallel, so at any
// moment some of them do not exist. A scene that only works once every asset
// lands is a scene nobody can look at while it is being made: everything here
// loads what is present, records what is not, and puts a clearly-marked
// temporary ground at the ART-DIRECTION §6.1 levels if the real ground is
// missing.

import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { tuneMaterials } from './materials.js';
import { COOL } from './palette.js';

const loader = new GLTFLoader();

function tris(geometry) {
  const idx = geometry.getIndex();
  return (idx ? idx.count : geometry.getAttribute('position').count) / 3;
}

async function tryLoad(url) {
  try {
    const gltf = await loader.loadAsync(url);
    return gltf.scene;
  } catch (err) {
    return null;
  }
}

/**
 * Flatten a loaded glTF root into geometry+material pairs with the node
 * transforms baked in, so it can drive an InstancedMesh.
 */
function flatten(root) {
  root.updateWorldMatrix(true, true);
  const inv = new THREE.Matrix4().copy(root.matrixWorld).invert();
  const parts = [];
  root.traverse((o) => {
    if (!o.isMesh) return;
    const local = new THREE.Matrix4().multiplyMatrices(inv, o.matrixWorld);
    const mats = Array.isArray(o.material) ? o.material : [o.material];
    const geo = o.geometry.clone();
    geo.applyMatrix4(local);
    parts.push({ geometry: geo, material: mats[0] });
  });
  return parts;
}

const UP = new THREE.Vector3(0, 1, 0);

/** Compose one instance matrix from a placement record out of place.js. */
function instanceMatrix(rec, m = new THREE.Matrix4()) {
  const up = new THREE.Vector3().fromArray(rec.up);
  const align = new THREE.Quaternion().setFromUnitVectors(UP, up);
  const yaw = new THREE.Quaternion().setFromAxisAngle(UP, rec.yaw);
  const q = align.multiply(yaw);
  return m.compose(new THREE.Vector3().fromArray(rec.p), q, new THREE.Vector3(rec.s, rec.s, rec.s));
}

export class SceneAssets {
  constructor() {
    this.root = new THREE.Group();
    this.root.name = 'world';
    this.loaded = [];
    this.missing = [];
    this.triangles = 0;
    this.instancedMeshes = 0;
    // key `${assetId}#${placementIndex}` -> emissive materials, for the flicker
    this.emissiveByPlacement = new Map();
    this.transparent = [];
  }

  async loadScenery(entries, base) {
    for (const e of entries) {
      const src = await tryLoad(`${base}/${e.file}`);
      if (!src) { this.missing.push({ ...e, why: 'not built yet' }); continue; }
      src.name = e.id;
      const found = tuneMaterials(src, {
        assetId: e.id,
        castShadow: e.castShadow !== false,
        receiveShadow: e.receiveShadow === true,
      });
      this.transparent.push(...found.transparent);
      const at = e.at[0];
      src.position.fromArray(at.pos);
      if (at.rotY) src.rotation.y = at.rotY;
      src.traverse((o) => { if (o.isMesh) this.triangles += tris(o.geometry); });
      this.root.add(src);
      this.loaded.push(e);
    }
  }

  /**
   * @param {Terrain|null} terrain  when a placement sets `seat: true`, its y is
   *   sampled from the terrain rather than written down, so the piece cannot
   *   float or bury itself when build_ground.py is re-run (acceptance item 4).
   */
  async loadFixtures(entries, base, terrain = null) {
    for (const e of entries) {
      const src = await tryLoad(`${base}/${e.file}`);
      if (!src) { this.missing.push({ ...e, why: 'not built yet' }); continue; }

      e.at.forEach((at, i) => {
        const obj = src.clone(true);
        // Per-placement material clones: four braziers that share one material
        // would flicker in lock-step, which reads instantly as a loop.
        obj.traverse((o) => {
          if (!o.isMesh) return;
          o.material = Array.isArray(o.material) ? o.material.map((m) => m.clone()) : o.material.clone();
        });
        const found = tuneMaterials(obj, { assetId: e.id, castShadow: false, receiveShadow: false });
        if (found.emissive.length) this.emissiveByPlacement.set(`${e.id}#${i}`, found.emissive);
        this.transparent.push(...found.transparent);

        obj.name = `${e.id}#${i}${at.tag ? ` (${at.tag})` : ''}`;
        if (at.seat) {
          const [x, , z] = at.pos;
          const y = terrain ? terrain.height(x, z) : at.pos[1];
          obj.position.set(x, y + (at.lift || 0), z);
        } else {
          obj.position.fromArray(at.pos);
        }
        if (at.rotY) obj.rotation.y = at.rotY;
        // A tipped cart needs a roll as well as a yaw. Setting Object3D.rotation
        // here is safe: it and .quaternion are the same state in three, so this
        // replaces whatever the loader put on the clone's root rather than being
        // silently ignored the way rotation_euler is on an imported Blender node.
        if (at.rot) obj.rotation.set(at.rot[0], at.rotY || at.rot[1], at.rot[2]);
        if (at.scale) obj.scale.fromArray(at.scale);
        obj.traverse((o) => { if (o.isMesh) this.triangles += tris(o.geometry); });
        this.root.add(obj);
      });
      this.loaded.push(e);
    }
  }

  async loadKits(entries, base, placement) {
    for (const e of entries) {
      const src = await tryLoad(`${base}/${e.file}`);
      if (!src) { this.missing.push({ ...e, why: 'not built yet' }); continue; }

      const records = placement[e.id] || [];
      if (!records.length) { this.missing.push({ ...e, why: 'no placement records' }); continue; }
      e.placedCount = records.length;

      tuneMaterials(src, { assetId: e.id, castShadow: e.castShadow !== false });
      const parts = flatten(src);
      const group = new THREE.Group();
      group.name = e.id;

      const m = new THREE.Matrix4();
      for (const part of parts) {
        const inst = new THREE.InstancedMesh(part.geometry, part.material, records.length);
        inst.name = `${e.id}:${part.material.name || 'mat'}`;
        inst.castShadow = e.castShadow !== false;
        inst.receiveShadow = e.receiveShadow === true;
        inst.instanceMatrix.setUsage(THREE.StaticDrawUsage);
        records.forEach((rec, i) => inst.setMatrixAt(i, instanceMatrix(rec, m)));
        inst.instanceMatrix.needsUpdate = true;
        inst.computeBoundingSphere();
        group.add(inst);
        this.triangles += tris(part.geometry) * records.length;
        this.instancedMeshes++;
      }
      this.root.add(group);
      this.loaded.push({ ...e, placed: records.length });
    }
  }

  /**
   * ART-DIRECTION §6.1 levels, as a stand-in, only when the real ground has not
   * been built. Named TEMPORARY_* so it cannot be mistaken for the article and
   * so the notes panel can say out loud that it is there.
   */
  addTemporaryGround() {
    const g = new THREE.Group();
    g.name = 'TEMPORARY_ground';

    const turf = new THREE.MeshStandardMaterial({ color: COOL.turfNight, roughness: 0.95, metalness: 0 });
    const rock = new THREE.MeshStandardMaterial({ color: 0x2A2B28, roughness: 0.95, metalness: 0 });

    const outfield = new THREE.Mesh(new THREE.PlaneGeometry(400, 400, 1, 1), turf);
    outfield.name = 'TEMPORARY_ground_outfield';
    outfield.rotation.x = -Math.PI / 2;
    outfield.position.y = -4.5;                 // §6.1 outfield, general
    outfield.receiveShadow = true;
    g.add(outfield);

    const platform = new THREE.Mesh(new THREE.BoxGeometry(104, 4.5, 88), rock);
    platform.name = 'TEMPORARY_ground_platform';
    platform.position.y = -2.25;                // top face at 0.0, the ward floor
    platform.castShadow = true;
    platform.receiveShadow = true;
    g.add(platform);

    this.root.add(g);
    this.temporaryGround = true;
    return g;
  }
}
